/**
 * Tracks whether an agent run may have left the game paused and guarantees
 * best-effort restoration before the bridge shuts down.
 */
export function createBridgeLifecycle(bridge) {
    let shouldUnpause = false;

    return {
        async pause() {
            // Set this before the RPC: a timeout can still mean the game applied it.
            shouldUnpause = true;
            await bridge.setPaused(true);
        },

        async release() {
            if (!shouldUnpause) return;
            await bridge.setPaused(false);
            shouldUnpause = false;
        },

        async cleanup() {
            try {
                if (shouldUnpause) {
                    await bridge.setPaused(false).catch(() => {});
                    shouldUnpause = false;
                }
            } finally {
                await bridge.stop();
            }
        },
    };
}

// Drives every bridge RPC by hand, no model involved. Run this first — if it
// passes, the bridge works and anything that breaks later is agent logic.
//
//   1. node server/serve-mod.mjs      (terminal 1)
//   2. yarn gulp in the shapez repo   (terminal 2)
//   3. node scripts/smoke.mjs         (terminal 3), then start a game

import { GameBridge } from "../server/bridge-server.mjs";

const bridge = new GameBridge().start();

function heading(text) {
    console.log(`\n=== ${text} ===`);
}

async function main() {
    console.log("Waiting for shapez to launch...");
    await bridge.waitForGame();
    console.log("Connected. Now waiting for a savegame to be loaded.");

    const status = await bridge.waitForInGame({
        onWait: () => console.log("  (still at the main menu — start or load a game)"),
    });

    heading("ping");
    console.log(status);

    heading("unlocked buildings");
    const buildings = await bridge.buildings();
    console.log(
        buildings
            .filter(b => b.unlocked)
            .map(b => b.id)
            .join(", ")
    );

    heading("observe");
    const state = await bridge.observe({ radius: 25 });
    console.log("hub:      ", state.hub);
    console.log("level:    ", state.level);
    console.log("goal:     ", state.goal);
    console.log("rates:    ", state.rates);
    console.log("patches:  ", state.patches.slice(0, 5));
    console.log("entities: ", state.entities.length);
    if (state.ascii) console.log(`\n${state.ascii.grid}`);

    // Pause so `run` is the only thing advancing time — makes results repeatable.
    heading("pause");
    console.log(await bridge.setPaused(true));

    // Place a belt somewhere clear of the hub (which occupies a 4x4 at -2,-2).
    const testTile = { x: state.hub.x + 8, y: state.hub.y + 8 };
    heading(`place belt at (${testTile.x},${testTile.y})`);
    try {
        console.log(await bridge.place({ type: "belt", ...testTile, rotation: 90 }));
    } catch (ex) {
        console.log("placement failed:", ex.message);
    }

    heading("place_many (a short belt run)");
    const run = [];
    for (let i = 1; i <= 4; ++i) {
        run.push({ type: "belt", x: testTile.x + i, y: testTile.y, rotation: 90 });
    }
    console.log(await bridge.placeMany(run));

    heading("run 15s");
    console.log(await bridge.run(15));

    heading("cleanup");
    for (let i = 0; i <= 4; ++i) {
        try {
            await bridge.remove(testTile.x + i, testTile.y);
        } catch (ex) {
            console.log(`  remove (${testTile.x + i},${testTile.y}): ${ex.message}`);
        }
    }
    console.log(await bridge.setPaused(false));

    console.log("\nSmoke test finished.");
    await bridge.stop();
    process.exit(0);
}

main().catch(async err => {
    console.error("\nSmoke test failed:", err.message);
    await bridge.stop();
    process.exit(1);
});

// End-to-end test of the agent loop with no API key and no game.
//
// A local HTTP server stands in for the Claude API and a WebSocket client
// stands in for shapez, so this exercises the real path: tool schemas → tool
// runner → dispatcher → bridge → game, and the results back again.

import { createServer } from "node:http";
import Anthropic from "@anthropic-ai/sdk";
import { betaTool } from "@anthropic-ai/sdk/helpers/beta/json-schema";
import WebSocket from "ws";
import { GameBridge } from "../server/bridge-server.mjs";
import { TOOLS, createDispatcher } from "../server/tools.mjs";
import { SYSTEM_PROMPT } from "../agent/prompt.mjs";

let failures = 0;
let checks = 0;
function check(name, cond, extra = "") {
    checks++;
    if (!cond) failures++;
    console.log(`${cond ? "PASS" : "FAIL"}  ${name}${extra ? " — " + extra : ""}`);
}

// --- stand-in for the Claude API --------------------------------------------

const requests = [];
let step = 0;

function assistantMessage(content, stopReason) {
    return {
        id: `msg_${++step}`,
        type: "message",
        role: "assistant",
        model: "claude-opus-5",
        content,
        stop_reason: stopReason,
        stop_sequence: null,
        usage: { input_tokens: 10, output_tokens: 10 },
    };
}

// Scripted turns: observe, then connect, then finish.
const SCRIPT = [
    () =>
        assistantMessage(
            [
                { type: "text", text: "Looking at the map first." },
                { type: "tool_use", id: "toolu_1", name: "observe", input: { radius: 20 } },
            ],
            "tool_use"
        ),
    () =>
        assistantMessage(
            [
                {
                    type: "tool_use",
                    id: "toolu_2",
                    name: "connect",
                    input: { from_x: 5, from_y: 5, to_x: 5, to_y: 0 },
                },
            ],
            "tool_use"
        ),
    () => assistantMessage([{ type: "text", text: "Line built and verified." }], "end_turn"),
];

const api = createServer((req, res) => {
    let body = "";
    req.on("data", chunk => (body += chunk));
    req.on("end", () => {
        requests.push({ url: req.url, body: JSON.parse(body || "{}") });
        const handler = SCRIPT[requests.length - 1] || SCRIPT[SCRIPT.length - 1];
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify(handler()));
    });
});
await new Promise(resolve => api.listen(0, resolve));
const apiPort = api.address().port;

// --- stand-in for shapez -----------------------------------------------------

const bridge = new GameBridge({ port: 8798, log: () => {} }).start();
const gameCalls = [];
const game = new WebSocket("ws://127.0.0.1:8798");
game.on("message", raw => {
    const { id, method, params } = JSON.parse(raw.toString());
    gameCalls.push({ method, params });
    const replies = {
        setPaused: () => ({ paused: params.paused }),
        observe: () => ({
            hub: { x: -2, y: -2, w: 4, h: 4 },
            level: 1,
            goal: { shape: "CuCuCuCu", required: 30, delivered: 0 },
            rates: { minerItemsPerSecond: 1.5 },
            patches: [{ x: 5, y: 5, kind: "shape", item: "CuCuCuCu", size: 9 }],
            entities: [],
        }),
        connect: () => ({ placed: 4, turns: 0 }),
    };
    game.send(JSON.stringify({ id, ok: true, result: (replies[method] || (() => ({})))() }));
});
await bridge.waitForGame(5000);

// --- run the loop ------------------------------------------------------------

const dispatch = createDispatcher(bridge);
const executed = [];

const tools = TOOLS.map(spec =>
    betaTool({
        name: spec.name,
        description: spec.description,
        inputSchema: spec.input_schema,
        run: async input => {
            executed.push(spec.name);
            return JSON.stringify(await dispatch(spec.name, input));
        },
    })
);

const client = new Anthropic({
    apiKey: "test-key-not-real",
    baseURL: `http://127.0.0.1:${apiPort}`,
    maxRetries: 0,
});

const runner = client.beta.messages.toolRunner({
    model: "claude-opus-5",
    max_tokens: 16000,
    system: SYSTEM_PROMPT,
    output_config: { effort: "high" },
    tools,
    messages: [{ role: "user", content: "Build a line." }],
    max_iterations: 10,
});

const turns = [];
for await (const message of runner) turns.push(message);

// --- assertions --------------------------------------------------------------

console.log("=== agent loop ===");
check("loop ran to completion", turns.length === 3, `${turns.length} turns`);
check("finished on end_turn", turns[turns.length - 1]?.stop_reason === "end_turn");
check("executed the tools the model asked for",
    executed.join(",") === "observe,connect", executed.join(",") || "none");
check("tool calls reached the game",
    gameCalls.some(c => c.method === "observe") && gameCalls.some(c => c.method === "connect"));

console.log("\n=== request shape the API actually received ===");
const first = requests[0].body;
check("model is claude-opus-5", first.model === "claude-opus-5", first.model);
check("effort is set", first.output_config?.effort === "high", JSON.stringify(first.output_config));
check("system prompt is attached", typeof first.system === "string" && first.system.length > 100);
check("all 7 tools are declared", first.tools?.length === 7, `${first.tools?.length}`);
check("tool schemas survive the round trip",
    first.tools.every(t => t.name && t.description && t.input_schema?.type === "object"));
check("connect is among them", first.tools.some(t => t.name === "connect"));

console.log("\n=== conversation threading ===");
const second = requests[1].body;
const hasToolResult = second.messages.some(
    m => m.role === "user" && Array.isArray(m.content) &&
         m.content.some(b => b.type === "tool_result" && b.tool_use_id === "toolu_1")
);
check("tool result is fed back with the matching id", hasToolResult);
const resultBlock = second.messages
    .flatMap(m => (Array.isArray(m.content) ? m.content : []))
    .find(b => b.type === "tool_result");
check("  it carries the game's observation",
    JSON.stringify(resultBlock?.content ?? "").includes("CuCuCuCu"));
check("history grows across turns", requests[2].body.messages.length > second.messages.length);

console.log("\n=== refusal path ===");
{
    // A refusal is a 200 with stop_reason "refusal" — the loop must not try to
    // read content blocks that may be absent.
    const refusal = assistantMessage([], "refusal");
    refusal.stop_details = { type: "refusal", category: "cyber" };
    let readOk = true;
    try {
        if (refusal.stop_reason === "refusal") {
            void refusal.stop_details?.category;
            for (const b of refusal.content) void b.type;
        }
    } catch {
        readOk = false;
    }
    check("empty-content refusal is safe to handle", readOk);
}

// Close in dependency order and let the event loop drain. Tearing the
// WebSocket server down underneath a live client, then exiting immediately,
// trips a libuv assertion on Windows.
game.close();
await new Promise(resolve => game.once("close", resolve));
await bridge.stop();
await new Promise(resolve => api.close(resolve));

console.log(failures ? `\n${failures} of ${checks} checks FAILED` : `\nAll ${checks} checks passed`);
process.exitCode = failures ? 1 : 0;

// Stubs the game side of the protocol to verify the bridge's RPC layer.
import { EventEmitter, once } from "node:events";
import WebSocket from "ws";
import { GameBridge } from "../server/bridge-server.mjs";
import { TOOLS, createDispatcher } from "../server/tools.mjs";

const bridge = new GameBridge({ port: 8799, log: () => {} }).start();
const dispatch = createDispatcher(bridge);
let failures = 0;

function check(name, cond, extra = "") {
    console.log(`${cond ? "PASS" : "FAIL"}  ${name}${extra ? " — " + extra : ""}`);
    if (!cond) failures++;
}

// Fake game: answers the same methods the mod implements.
const game = new WebSocket("ws://127.0.0.1:8799");
game.on("message", raw => {
    const { id, method, params } = JSON.parse(raw.toString());
    const replies = {
        ping: () => ({ pong: true, inGame: true }),
        observe: () => ({
            hub: { x: -2, y: -2, w: 4, h: 4 },
            level: 1,
            goal: { shape: "CuCuCuCu", required: 30, delivered: 0 },
            rates: { beltItemsPerSecond: 6, minerItemsPerSecond: 1.5 },
            patches: [{ x: 10, y: 4, kind: "shape", item: "CuCuCuCu", size: 9 }],
            entities: [["hub", -2, -2, 0, "default", 1]],
            radiusEcho: params.radius,
            portsEcho: params.includePorts,
        }),
        buildings: () => [{ id: "belt", unlocked: true }, { id: "miner", unlocked: true }],
        place: () => ({ uid: 42, ...params }),
        placeMany: () => ({ placed: params.entities.length, failures: [] }),
        remove: () => ({ removed: true }),
        setPaused: () => ({ paused: params.paused }),
        run: () => ({ ticks: 900, elapsedSeconds: 15, deliveredDelta: { CuCuCuCu: { count: 3, perSecond: 0.2 } } }),
        boom: () => { throw new Error("simulated game-side failure"); },
    };
    try {
        game.send(JSON.stringify({ id, ok: true, result: replies[method]() }));
    } catch (ex) {
        game.send(JSON.stringify({ id, ok: false, error: String(ex.message) }));
    }
});

await bridge.waitForGame(5000);

let duplicateStartRejected = false;
try {
    bridge.start();
} catch (ex) {
    duplicateStartRejected = ex.message.includes("already started");
}
check("starting an active bridge is rejected", duplicateStartRejected);

// --- request/response plumbing ---
check("ping round-trips", (await bridge.ping()).pong === true);
const obs = await bridge.observe({ radius: 25 });
check("observe returns state", obs.goal.shape === "CuCuCuCu");
check("params reach the game", obs.radiusEcho === 25);

// --- concurrent calls must not cross wires ---
const [a, b, c] = await Promise.all([bridge.buildings(), bridge.ping(), bridge.run(15)]);
check("concurrent calls resolve independently",
    Array.isArray(a) && b.pong === true && c.ticks === 900);

// Invalid durations must fail before an RPC can lock the game into an
// effectively unbounded synchronous update loop.
for (const seconds of [0, -1, NaN, Infinity, 301]) {
    let invalidRunRejected = false;
    try {
        await bridge.run(seconds);
    } catch (ex) {
        invalidRunRejected = ex.message.includes("finite number");
    }
    check(`run rejects unsafe duration ${String(seconds)}`, invalidRunRejected);
}

// --- game-side errors surface as rejections ---
let rejected = false;
try { await bridge.call("boom"); } catch (ex) { rejected = ex.message.includes("simulated"); }
check("game-side error rejects with its message", rejected);

// --- tool dispatch layer ---
const viaTool = await dispatch("observe", { radius: 12, include_ports: false });
check("dispatcher maps snake_case to bridge args",
    viaTool.radiusEcho === 12 && viaTool.portsEcho === false);
const unknown = await dispatch("nope", {});
check("unknown tool returns error, doesn't throw", typeof unknown.error === "string");

// --- tool schema sanity ---
check("every tool has name/description/input_schema",
    TOOLS.every(t => t.name && t.description && t.input_schema?.type === "object"));
check("every dispatcher key has a schema and vice versa",
    TOOLS.every(t => typeof dispatch === "function") && TOOLS.length === 7,
    `${TOOLS.length} tools`);
const runSecondsSchema = TOOLS.find(t => t.name === "run")?.input_schema?.properties?.seconds;
check("run schema excludes non-positive durations", runSecondsSchema?.exclusiveMinimum === 0);
check("run schema caps synchronous simulation work", runSecondsSchema?.maximum === 300);
for (const t of TOOLS) {
    const r = await dispatch(t.name, {});
    check(`  dispatch(${t.name}) reaches the game`, !r?.error || !r.error.startsWith("Unknown tool"));
}

// --- replacement socket close events must not poison the new connection ---
class FakeSocket extends EventEmitter {
    constructor() {
        super();
        this.OPEN = 1;
        this.readyState = this.OPEN;
        this.sent = [];
        this.terminated = false;
    }
    send(raw) {
        this.sent.push(JSON.parse(raw));
    }
    terminate() {
        this.terminated = true;
    }
}

const reconnectBridge = new GameBridge({ log: () => {} });
const oldSocket = new FakeSocket();
const newSocket = new FakeSocket();
reconnectBridge.handleConnection(oldSocket);

const oldCall = reconnectBridge.call("old-request", {}, 5000);
reconnectBridge.handleConnection(newSocket);
let replacementHandled = false;
try { await oldCall; } catch (ex) { replacementHandled = ex.message.includes("replaced"); }
check("replacement rejects calls sent through the old socket", replacementHandled);
check("replacement terminates the old socket", oldSocket.terminated);

const newCall = reconnectBridge.call("new-request", {}, 5000);
oldSocket.emit("close");
const [{ id: newCallId }] = newSocket.sent;
reconnectBridge.onMessage(JSON.stringify({ id: newCallId, ok: true, result: "new response" }));
check("stale close leaves new-socket calls alive", (await newCall) === "new response");

// --- send failures reject immediately and release pending state ---
const throwingSocket = new FakeSocket();
throwingSocket.send = () => { throw new Error("socket write failed"); };
const throwingBridge = new GameBridge({ log: () => {} });
throwingBridge.handleConnection(throwingSocket);
let synchronousSendRejected = false;
try {
    await throwingBridge.call("sync-send-failure", {}, 5000);
} catch (ex) {
    synchronousSendRejected = ex.message.includes("socket write failed");
}
check("synchronous send failure rejects with its cause", synchronousSendRejected);
check("synchronous send failure clears pending state", throwingBridge.pending.size === 0);

const callbackSocket = new FakeSocket();
callbackSocket.send = (_raw, callback) => {
    queueMicrotask(() => callback(new Error("send callback failed")));
};
const callbackBridge = new GameBridge({ log: () => {} });
callbackBridge.handleConnection(callbackSocket);
let callbackSendRejected = false;
try {
    await callbackBridge.call("callback-send-failure", {}, 5000);
} catch (ex) {
    callbackSendRejected = ex.message.includes("send callback failed");
}
check("send callback failure rejects with its cause", callbackSendRejected);
check("send callback failure clears pending state", callbackBridge.pending.size === 0);

// --- connection waiters settle and release their timers ---
const timeoutBridge = new GameBridge({ log: () => {} });
let connectTimedOut = false;
try {
    await timeoutBridge.waitForGame(5);
} catch (ex) {
    connectTimedOut = ex.message.includes("No game connected");
}
check("connection wait timeout rejects", connectTimedOut);
check("timed-out connection waiter is removed", timeoutBridge.waitingForConnect.size === 0);

const stoppedBridge = new GameBridge({ log: () => {} });
const stoppedWaiter = stoppedBridge.waitForGame(5000);
const stoppedBridgeClose = stoppedBridge.stop();
let stopRejectedWaiter = false;
try {
    await stoppedWaiter;
} catch (ex) {
    stopRejectedWaiter = ex.message.includes("Bridge stopped");
}
await stoppedBridgeClose;
check("stopping the bridge rejects connection waiters", stopRejectedWaiter);
check("stopping the bridge removes connection waiters", stoppedBridge.waitingForConnect.size === 0);
let waitAfterStopRejected = false;
try {
    await stoppedBridge.waitForGame();
} catch (ex) {
    waitAfterStopRejected = ex.message.includes("Bridge stopped");
}
check("a stopped bridge does not report a stale connection", waitAfterStopRejected);

// --- waitForInGame uses one timeout budget across connection and polling ---
const budgetBridge = new GameBridge({ log: () => {} });
const mainMenuSocket = new FakeSocket();
mainMenuSocket.send = (raw, callback) => {
    const { id } = JSON.parse(raw);
    callback?.();
    queueMicrotask(() => {
        budgetBridge.onMessage(JSON.stringify({ id, ok: true, result: { inGame: false } }));
    });
};
const budgetStarted = Date.now();
setTimeout(() => budgetBridge.handleConnection(mainMenuSocket), 70);
let inGameTimedOut = false;
try {
    await budgetBridge.waitForInGame({ timeoutMs: 100, pollMs: 5 });
} catch (ex) {
    inGameTimedOut = ex.message.includes("main menu");
}
const budgetElapsed = Date.now() - budgetStarted;
check("in-game wait reports its timeout", inGameTimedOut);
check("connection time counts against the in-game timeout", budgetElapsed < 140, `${budgetElapsed}ms`);

// --- disconnect fails in-flight calls instead of hanging ---
const inflight = bridge.call("observe", {}, 5000);
game.terminate();
let disconnectHandled = false;
try { await inflight; } catch (ex) { disconnectHandled = ex.message.includes("disconnected"); }
check("disconnect rejects in-flight calls", disconnectHandled);

await bridge.stop();
check("stop clears live socket and server references", bridge.socket === null && bridge.server === null);

bridge.start();
await once(bridge.server, "listening");
check("a fully stopped bridge can restart on the same port", bridge.server.address().port === 8799);
await bridge.stop();
await bridge.stop();
check("stopping an already stopped bridge is harmless", bridge.server === null);

console.log(failures ? `\n${failures} FAILED` : "\nAll checks passed");
process.exit(failures ? 1 : 0);

// WebSocket server the shapez mod connects out to.
//
// The game runs in a browser and browsers can't listen, so the agent side hosts
// and the game dials in. One game at a time — a second connection replaces the
// first (that's a page reload, not a second player).

import { WebSocketServer } from "ws";
import { readIntegerEnv } from "./env.mjs";

const PORT = readIntegerEnv("BRIDGE_PORT", process.env.BRIDGE_PORT, 8765, { max: 65_535 });
const DEFAULT_TIMEOUT_MS = 30_000;
export const MAX_RUN_SECONDS = 300;

export function validateRunSeconds(seconds) {
    if (typeof seconds !== "number" || !Number.isFinite(seconds) || seconds <= 0 || seconds > MAX_RUN_SECONDS) {
        throw new Error(`seconds must be a finite number greater than 0 and no more than ${MAX_RUN_SECONDS}`);
    }
    return seconds;
}

export class GameBridge {
    constructor({ port = PORT, log = console.log } = {}) {
        this.port = port;
        this.log = log;
        this.socket = null;
        this.nextId = 1;
        /** @type {Map<number, {resolve: Function, reject: Function, timer: any}>} */
        this.pending = new Map();
        /** @type {Set<{resolve: Function, reject: Function, timer: any}>} */
        this.waitingForConnect = new Set();
        this.server = null;
        this.stopped = false;
    }

    start() {
        if (this.server) throw new Error("Bridge server is already started");

        this.stopped = false;
        this.server = new WebSocketServer({ port: this.port });
        this.log(`[bridge] listening on ws://127.0.0.1:${this.port}`);

        this.server.on("connection", socket => this.handleConnection(socket));

        return this;
    }

    handleConnection(socket) {
        if (this.stopped) {
            socket.terminate();
            return;
        }
        if (this.socket) {
            this.log("[bridge] replacing previous connection");
            this.failAllPending(new Error("Game connection replaced"));
            this.socket.terminate();
        }
        this.socket = socket;
        this.log("[bridge] game connected");

        const waiters = [...this.waitingForConnect];
        this.waitingForConnect.clear();
        for (const waiter of waiters) {
            clearTimeout(waiter.timer);
            waiter.resolve();
        }

        socket.on("message", raw => this.onMessage(raw));
        socket.on("close", () => {
            // A replaced socket can close after the new connection is already
            // serving RPCs. Its stale close event must not reject those calls.
            if (this.socket !== socket) return;
            this.socket = null;
            this.log("[bridge] game disconnected");
            this.failAllPending(new Error("Game disconnected"));
        });
        socket.on("error", err => this.log("[bridge] socket error:", err.message));
    }

    stop() {
        this.stopped = true;
        this.failAllPending(new Error("Bridge stopped"));
        this.failAllConnectWaiters(new Error("Bridge stopped"));
        const socket = this.socket;
        this.socket = null;
        if (socket) socket.terminate();

        const server = this.server;
        this.server = null;
        if (!server) return Promise.resolve();

        return new Promise((resolve, reject) => {
            server.close(error => error ? reject(error) : resolve());
        });
    }

    /** Resolves once the game process has connected its socket. */
    waitForGame(timeoutMs = 120_000) {
        if (this.stopped) return Promise.reject(new Error("Bridge stopped"));
        if (this.socket && this.socket.readyState === this.socket.OPEN) return Promise.resolve();
        return new Promise((resolve, reject) => {
            const waiter = { resolve, reject, timer: null };
            waiter.timer = setTimeout(() => {
                this.waitingForConnect.delete(waiter);
                reject(new Error(`No game connected after ${timeoutMs}ms`));
            }, timeoutMs);
            this.waitingForConnect.add(waiter);
        });
    }

    /**
     * Resolves once a savegame is actually loaded.
     *
     * The mod connects at app boot, so a live socket only means the game is
     * running — at the main menu there is no root and every RPC but `ping`
     * fails. Poll until it reports in-game.
     */
    async waitForInGame({ timeoutMs = 600_000, pollMs = 1000, onWait } = {}) {
        const deadline = Date.now() + timeoutMs;
        await this.waitForGame(timeoutMs);
        let announced = false;

        for (;;) {
            const remainingBeforePing = deadline - Date.now();
            if (remainingBeforePing <= 0) {
                throw new Error(`Still at the main menu after ${Math.round(timeoutMs / 1000)}s`);
            }

            const status = await this.call(
                "ping",
                {},
                Math.min(DEFAULT_TIMEOUT_MS, remainingBeforePing)
            ).catch(() => null);
            if (status?.inGame) return status;

            if (!announced && onWait) {
                onWait();
                announced = true;
            }
            const remaining = deadline - Date.now();
            if (remaining <= 0) {
                throw new Error(`Still at the main menu after ${Math.round(timeoutMs / 1000)}s`);
            }
            await new Promise(resolve => setTimeout(resolve, Math.min(pollMs, remaining)));
        }
    }

    onMessage(raw) {
        let msg;
        try {
            msg = JSON.parse(raw.toString());
        } catch (ex) {
            this.log("[bridge] unparseable message from game");
            return;
        }

        // Unsolicited notifications (e.g. gameStarted) carry no id.
        if (msg.id === undefined) {
            this.log("[bridge] event:", msg.event || msg.type);
            return;
        }

        const entry = this.pending.get(msg.id);
        if (!entry) return;
        this.pending.delete(msg.id);
        clearTimeout(entry.timer);

        if (msg.ok) entry.resolve(msg.result);
        else entry.reject(new Error(msg.error || "Unknown game-side error"));
    }

    failAllPending(error) {
        for (const [, entry] of this.pending) {
            clearTimeout(entry.timer);
            entry.reject(error);
        }
        this.pending.clear();
    }

    failAllConnectWaiters(error) {
        for (const waiter of this.waitingForConnect) {
            clearTimeout(waiter.timer);
            waiter.reject(error);
        }
        this.waitingForConnect.clear();
    }

    /**
     * Sends an RPC request to the game and resolves with its result.
     * `run` can legitimately take a while, so give it a longer timeout.
     */
    call(method, params = {}, timeoutMs = DEFAULT_TIMEOUT_MS) {
        if (!this.socket || this.socket.readyState !== this.socket.OPEN) {
            return Promise.reject(new Error("No game connected"));
        }

        const socket = this.socket;
        const id = this.nextId++;
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                this.pending.delete(id);
                reject(new Error(`Timed out after ${timeoutMs}ms: ${method}`));
            }, timeoutMs);

            this.pending.set(id, { resolve, reject, timer });
            const failSend = error => {
                if (!error) return;
                const entry = this.pending.get(id);
                if (!entry) return;

                this.pending.delete(id);
                clearTimeout(entry.timer);
                const message = error instanceof Error ? error.message : String(error);
                reject(new Error(`Failed to send ${method}: ${message}`));
            };

            try {
                socket.send(JSON.stringify({ id, method, params }), failSend);
            } catch (error) {
                failSend(error);
            }
        });
    }

    // Convenience wrappers ---------------------------------------------------

    ping() {
        return this.call("ping");
    }
    observe(params = {}) {
        return this.call("observe", params);
    }
    buildings() {
        return this.call("buildings");
    }
    place(params) {
        return this.call("place", params);
    }
    placeMany(entities, atomic = false) {
        return this.call("placeMany", { entities, atomic });
    }
    remove(x, y) {
        return this.call("remove", { x, y });
    }
    connect(params) {
        return this.call("connect", params);
    }
    setPaused(paused) {
        return this.call("setPaused", { paused });
    }
    /** Stepping is synchronous game-side, so allow generous headroom. */
    run(seconds = 10) {
        const validatedSeconds = validateRunSeconds(seconds);
        return this.call(
            "run",
            { seconds: validatedSeconds },
            Math.max(60_000, validatedSeconds * 2000)
        );
    }
}

// Run standalone: node server/bridge-server.mjs
if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, "/")}`) {
    const bridge = new GameBridge().start();
    process.on("SIGINT", async () => {
        await bridge.stop();
        process.exit(0);
    });
}
